@pytest.mark.parametrize("data", [info("internal_user"), info("proxy_admin_viewer"), info("team_admin"),
    info(blocked=True), info(deleted=True), info(is_active=False), {**info(), "user_id": "spoofed"}, {}, (401, {}), (403, {})])
