@pytest.mark.parametrize("data", [(500, {}), (302, {}), [], TimeoutError(), "not-json-object"])
@pytest.mark.asyncio
async def test_identity_errors_fail_closed(data):
    with pytest.raises(AuthorizationUnavailable):
